from itertools import permutations

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            v = (dc, dr)
            if v in vectors:
                return False
            vectors.add(v)
    return True

def solve_costas_partial(n, fixed):
    """Solve Costas array with fixed assignments using backtracking."""
    perm = [None] * n

    # Set fixed values
    for col, row in fixed.items():
        perm[col] = row

    used_rows = set(v for v in perm if v is not None)

    def check_partial(perm, col):
        """Check if adding perm[col] creates any duplicate displacement vector."""
        vectors = set()
        for i in range(col):
            if perm[i] is None:
                continue
            for j in range(i+1, col+1):
                if perm[j] is None:
                    continue
                dc = j - i
                dr = perm[j] - perm[i]
                v = (dc, dr)
                if v in vectors:
                    return False
                vectors.add(v)
        return True

    def backtrack(col, used_rows, vectors):
        if col == n:
            return True

        if perm[col] is not None:
            # Fixed value, just check validity
            if not check_partial(perm, col):
                return False
            return backtrack(col + 1, used_rows, vectors)

        for row in range(n):
            if row in used_rows:
                continue
            perm[col] = row
            used_rows.add(row)

            if check_partial(perm, col):
                if backtrack(col + 1, used_rows, vectors):
                    return True

            perm[col] = None
            used_rows.remove(row)

        return False

    used = set(v for v in perm if v is not None)
    if backtrack(0, used, set()):
        return perm
    return None

